using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;using SplifyWin;
class BrowserTrafficChecks20261023 {
 static void CopyTree(string a,string b){Directory.CreateDirectory(b);foreach(string f in Directory.GetFiles(a))File.Copy(f,Path.Combine(b,Path.GetFileName(f)));foreach(string d in Directory.GetDirectories(a))CopyTree(d,Path.Combine(b,Path.GetFileName(d)));}
 static int count;static JavaScriptSerializer json=new JavaScriptSerializer();static void Check(bool yes,string name){if(!yes)throw new Exception(name);Console.WriteLine("PASS "+(++count)+" "+name);}
 static EngineCatalog Clone(EngineCatalog c){return json.Deserialize<EngineCatalog>(json.Serialize(c));}
static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);if(args.Length>1&&Directory.Exists(args[1]))foreach(string id in (args.Contains("--download")?new[]{"csqtt25"}:new[]{"csqtt25","csqtt-bridge"}))CopyTree(Path.Combine(args[1],"optional-engines-v2",id),Path.Combine(root,"optional-engines-v2",id));RuntimeResources.Prepare(root);var core=new NetworkCore(new StateStore(root));var embedded=new EngineCatalog{Version=1,Engines=core.Engines.Packages.ToList()};if(args.Contains("--download")){Check(!core.Engines.Installed("csqtt-bridge"),"public download starts with adapter absent");core.Engines.Install("csqtt-bridge").GetAwaiter().GetResult();Check(core.Engines.Installed("csqtt-bridge"),"real app downloader validates public bridge ZIP and extracted files");}Check(core.Engines.Package("csqtt-bridge").Version=="capacity-20261023-1","candidate selects fixed bridge");
  var old=Clone(embedded);old.Engines.Single(p=>p.Id=="csqtt-bridge").Version="vkturn-20261022-1";string openflux=old.Engines.Single(p=>p.Id=="openflux").Sha256;var upgraded=OptionalEngines.MergeEmbeddedRequirements(old,embedded);Check(upgraded.Engines.Single(p=>p.Id=="csqtt-bridge").Version=="capacity-20261023-1","cached old catalog cannot shadow fixed bridge");Check(upgraded.Engines.Single(p=>p.Id=="openflux").Sha256==openflux,"unrelated optional packages preserved");
  var future=Clone(embedded);future.Engines.Single(p=>p.Id=="csqtt-bridge").Version="capacity-20261024-1";Check(OptionalEngines.MergeEmbeddedRequirements(future,embedded).Engines.Single(p=>p.Id=="csqtt-bridge").Version=="capacity-20261024-1","future bridge not downgraded");
  var missing=Clone(embedded);missing.Engines.RemoveAll(p=>p.Id=="csqtt-bridge");Check(OptionalEngines.MergeEmbeddedRequirements(missing,embedded).Engines.Any(p=>p.Id=="csqtt-bridge"),"missing cached bridge restored to requirements");
  var n=Links.Read("socks5://127.0.0.1:19999").Single();var state=new ClientState{Mode="tun",DnsProvider="Системный",DnsProtocol="Системный",Servers=new List<ServerNode>{n},SelectedServerId=n.Id,AutoSelect=false,VpnEnabled=true,IndependentWarpOutputs=true};var c=core.Build(state);var dns=(Dictionary<string,object>)c["dns"];Check(Convert.ToBoolean(dns["reverse_mapping"]),"DNS reverse mapping enabled");var inbound=((IEnumerable)c["inbounds"]).Cast<Dictionary<string,object>>().First(x=>Convert.ToString(x["type"])=="tun");Check(Convert.ToString(inbound["dns_mode"])=="hijack","system DNS captured in TUN");var chosen=((IEnumerable)dns["servers"]).Cast<Dictionary<string,object>>().Single(x=>Convert.ToString(x["tag"])=="chosen");Check(Convert.ToString(chosen["type"])=="local","system resolver selection not silently replaced");Check(!json.Serialize(c["outbounds"]).Contains("mcrf_ipv4_only"),"generic SOCKS not marked IPv4-only");core.Check(core.WriteConfig(state));Check(true,"actual core accepts system DNS capture configuration");
  n=Links.Read("csqtt://connect?v=2&host=192.0.2.1&peer=56000&password=fixture&hashes="+new string('A',43)).Single();n.CsqttGeneration="2.5";state.Servers=new List<ServerNode>{n};state.SelectedServerId=n.Id;
  // Config generation is intentionally independent of live server credentials.
  try{c=core.Build(state);Check(json.Serialize(c["outbounds"]).Contains("mcrf_ipv4_only"),"CSQTT declares IPv4-only adapter");core.Check(core.WriteConfig(state));Check(true,"actual core accepts marked CSQTT SOCKS output");}catch(NotSupportedException){Console.WriteLine("SKIP CSQTT config: test profile has no optional transport installed");}
  Console.WriteLine("RESULT "+count+" PASS");return 0;
 }catch(Exception ex){Console.WriteLine("FAIL "+ex.GetType().Name+" "+JournalStyle.Redact(ex.Message));return 1;}}
}
